function(container, apiUrl, tables) {
  var MAX_CHARS = 2000;
  var textarea = container.querySelector('#daily-work-input');
  var charCountEl = container.querySelector('#char-count');
  var validationEl = container.querySelector('#validation-result');
  var submitBtn = container.querySelector('#btn-submit');
  var cancelBtn = container.querySelector('#btn-cancel');
  var submitStatusEl = container.querySelector('#submit-status');
  var emailStatusEl = container.querySelector('#email-status');
  var navBtn = container.querySelector('#btn-goto-management');

  function validate() {
    var value = textarea.value;
    var len = value.length;
    charCountEl.textContent = String(len);
    var trimmed = value.trim();
    var valid = true;
    var message = '入力内容は有効です';
    var color = 'var(--primary)';
    if (trimmed.length === 0) {
      valid = false;
      message = '業務内容を入力してください';
      color = '#c0392b';
    } else if (len > MAX_CHARS) {
      valid = false;
      message = String(len - MAX_CHARS) + '文字超過しています。' + String(MAX_CHARS) + '文字以内で入力してください';
      color = '#c0392b';
    }
    validationEl.textContent = message;
    validationEl.style.color = color;
    submitBtn.disabled = !valid;
    submitBtn.style.opacity = valid ? '1' : '0.5';
    submitBtn.style.cursor = valid ? 'pointer' : 'not-allowed';
    return valid;
  }

  textarea.addEventListener('input', validate);

  submitBtn.addEventListener('click', function() {
    if (!validate()) return;
    submitBtn.disabled = true;
    submitBtn.style.opacity = '0.5';
    submitStatusEl.style.display = 'none';
    emailStatusEl.style.display = 'none';

    var userTable = tables.find(function(t) { return t.tableName === 'ユーザー'; });
    var currentUser = (userTable && userTable.records && userTable.records[0]) || {};
    var dailyReportIndex = tables.findIndex(function(t) { return t.tableName === '日報'; });
    var mailIndex = tables.findIndex(function(t) { return t.tableName === 'メール送信履歴'; });
    var now = new Date().toISOString();

    var reportRecord = {
      ユーザーID: currentUser.ユーザーID || '',
      報告日: now,
      業務内容: textarea.value.trim(),
      作成日時: now,
      更新日時: now
    };

    var savePromise = dailyReportIndex !== -1 ? window.aivicApi.save(dailyReportIndex, reportRecord) : Promise.resolve(null);

    savePromise.then(function(saved) {
      if (mailIndex === -1) return null;
      return window.aivicApi.save(mailIndex, {
        ユーザーID: currentUser.ユーザーID || '',
        メールタイプ: '日報提出通知',
        送信先メールアドレス: currentUser.メールアドレス || 'admin@example.com',
        件名: '【日報提出】' + new Date().toLocaleDateString('ja-JP'),
        本文: '本日の日報が提出されました。\n' + reportRecord.業務内容,
        送信日時: now,
        送信ステータス: '成功',
        関連日報ID: (saved && (saved.id || saved.日報ID)) || '',
        再送信フラグ: false,
        作成日時: now
      });
    }).then(function() {
      submitStatusEl.textContent = '日報を提出しました。ご協力ありがとうございました。';
      submitStatusEl.style.display = 'block';
      emailStatusEl.textContent = '管理者へメール通知を送信しました。';
      emailStatusEl.style.display = 'block';
      textarea.value = '';
      validate();
    });
  });

  cancelBtn.addEventListener('click', function() {
    textarea.value = '';
    validate();
    submitStatusEl.style.display = 'none';
    emailStatusEl.style.display = 'none';
  });

  if (navBtn) {
    navBtn.addEventListener('click', function() {
      if (window.showScreen) window.showScreen('scr-1789983420567');
    });
  }

  validate();
}

function(container, apiUrl, tables) {
  var userTable = tables.find(function(t) { return t.tableName === 'ユーザー'; });
  var reportTable = tables.find(function(t) { return t.tableName === '日報'; });
  var logTable = tables.find(function(t) { return t.tableName === '日報未提出者検知ログ'; });
  var mailIndex = tables.findIndex(function(t) { return t.tableName === 'メール送信履歴'; });

  var users = (userTable && userTable.records) || [];
  var reports = (reportTable && reportTable.records) || [];
  var logs = (logTable && logTable.records) || [];

  function userById(id) {
    return users.find(function(u) { return u.ユーザーID === id; });
  }

  var submittedBody = container.querySelector('#submitted-tbody');
  var submittedCount = container.querySelector('#submitted-count');
  var unsubmittedBody = container.querySelector('#unsubmitted-tbody');
  var unsubmittedCount = container.querySelector('#unsubmitted-count');
  var searchInput = container.querySelector('#search-submitted');
  var statusMsg = container.querySelector('#status-message');
  var detailOverlay = container.querySelector('#detail-modal-overlay');
  var reminderOverlay = container.querySelector('#reminder-confirm-overlay');
  var reminderMessage = container.querySelector('#reminder-confirm-message');
  var confirmReminderBtn = container.querySelector('#confirm-reminder-btn');
  var cancelReminderBtn = container.querySelector('#cancel-reminder-btn');
  var closeDetailBtn = container.querySelector('#close-detail-modal');
  var bulkReminderBtn = container.querySelector('#btn-bulk-reminder');
  var settingsBtn = container.querySelector('#btn-reminder-settings');
  var backToInputBtn = container.querySelector('#btn-back-to-input');

  var reminderTarget = null;

  function showStatus(msg) {
    statusMsg.textContent = msg;
    statusMsg.style.display = 'block';
    setTimeout(function() { statusMsg.style.display = 'none'; }, 4000);
  }

  function closeModals() {
    detailOverlay.style.display = 'none';
    reminderOverlay.style.display = 'none';
  }
  closeDetailBtn.addEventListener('click', closeModals);
  cancelReminderBtn.addEventListener('click', closeModals);
  detailOverlay.addEventListener('click', function(e) { if (e.target === detailOverlay) closeModals(); });
  reminderOverlay.addEventListener('click', function(e) { if (e.target === reminderOverlay) closeModals(); });

  function escapeHtml(str) {
    return String(str == null ? '' : str).replace(/[&<>]/g, function(c) { return c === '&' ? '&amp;' : (c === '<' ? '&lt;' : '&gt;'); });
  }

  function renderSubmitted(filterText) {
    var sorted = reports.slice().sort(function(a, b) { return new Date(b.作成日時 || b.報告日) - new Date(a.作成日時 || a.報告日); });
    var filtered = sorted.filter(function(r) {
      if (!filterText) return true;
      var user = userById(r.ユーザーID);
      var name = user ? user.氏名 : '';
      return name.toLowerCase().indexOf(filterText.toLowerCase()) !== -1;
    });
    submittedCount.textContent = filtered.length + '件';
    if (filtered.length === 0) {
      submittedBody.innerHTML = '<tr><td colspan=\"4\" style=\"padding: calc(var(--space-unit) * 3); text-align:center; color: var(--text-muted); font-size:13px;\">該当する日報がありません</td></tr>';
      return;
    }
    submittedBody.innerHTML = filtered.map(function(r) {
      var user = userById(r.ユーザーID);
      var name = user ? user.氏名 : '不明';
      var dateStr = String(r.報告日 || '').slice(0, 10);
      var raw = r.業務内容 || '';
      var summary = raw.slice(0, 40) + (raw.length > 40 ? '…' : '');
      return '<tr data-id=\"' + escapeHtml(r.日報ID) + '\" style=\"border-bottom: 1px solid var(--border);\">' +
        '<td style=\"padding: calc(var(--space-unit) * 1.5); font-size: 13px; color: var(--text);\">' + escapeHtml(name) + '</td>' +
        '<td style=\"padding: calc(var(--space-unit) * 1.5); font-size: 13px; color: var(--text);\">' + escapeHtml(dateStr) + '</td>' +
        '<td style=\"padding: calc(var(--space-unit) * 1.5); font-size: 13px; color: var(--text);\">' + escapeHtml(summary) + '</td>' +
        '<td style=\"padding: calc(var(--space-unit) * 1.5); text-align:center;\"><button class=\"btn-detail\" data-id=\"' + escapeHtml(r.日報ID) + '\" style=\"padding: 4px 10px; font-size:12px; border:1px solid var(--border); background: transparent; color: var(--text); border-radius: var(--radius-control); cursor:pointer;\">詳細</button></td>' +
        '</tr>';
    }).join('');

    submittedBody.querySelectorAll('tr').forEach(function(tr) {
      tr.addEventListener('mouseenter', function() { tr.style.background = 'var(--bg-sidebar)'; });
      tr.addEventListener('mouseleave', function() { tr.style.background = 'transparent'; });
    });
    submittedBody.querySelectorAll('.btn-detail').forEach(function(btn) {
      btn.addEventListener('click', function() {
        var id = btn.getAttribute('data-id');
        var report = reports.find(function(r) { return r.日報ID === id; });
        if (!report) return;
        var user = userById(report.ユーザーID);
        container.querySelector('#detail-reporter').textContent = user ? user.氏名 : '不明';
        container.querySelector('#detail-date').textContent = String(report.報告日 || '').slice(0, 10);
        container.querySelector('#detail-content').textContent = report.業務内容 || '-';
        detailOverlay.style.display = 'flex';
      });
    });
  }

  function computeUnsubmitted() {
    var byUser = {};
    logs.forEach(function(log) {
      if (log.提出状況 === '提出済み') return;
      var uid = log.ユーザーID;
      var dateStr = String(log.対象日付 || '').slice(0, 10);
      if (!byUser[uid] || dateStr < byUser[uid]) byUser[uid] = dateStr;
    });
    return Object.keys(byUser).map(function(uid) { return { userId: uid, since: byUser[uid] }; });
  }

  function renderUnsubmitted() {
    var list = computeUnsubmitted();
    unsubmittedCount.textContent = list.length + '件';
    if (list.length === 0) {
      unsubmittedBody.innerHTML = '<tr><td colspan=\"4\" style=\"padding: calc(var(--space-unit) * 3); text-align:center; color: var(--text-muted); font-size:13px;\">未提出者はいません</td></tr>';
      return;
    }
    unsubmittedBody.innerHTML = list.map(function(item) {
      var user = userById(item.userId);
      var name = user ? user.氏名 : '不明';
      var dept = (user && user.部門) || '-';
      return '<tr style=\"border-bottom: 1px solid var(--border);\">' +
        '<td style=\"padding: calc(var(--space-unit) * 1.5); font-size: 13px; color: var(--text);\">' + escapeHtml(name) + '</td>' +
        '<td style=\"padding: calc(var(--space-unit) * 1.5); font-size: 13px; color: var(--text);\">' + escapeHtml(dept) + '</td>' +
        '<td style=\"padding: calc(var(--space-unit) * 1.5); font-size: 13px; color: var(--text);\">' + escapeHtml(item.since) + ' 〜 本日</td>' +
        '<td style=\"padding: calc(var(--space-unit) * 1.5); text-align:center;\"><button class=\"btn-remind\" data-user-id=\"' + escapeHtml(item.userId) + '\" style=\"padding: 4px 10px; font-size:12px; border:1px solid var(--primary); background: transparent; color: var(--primary); border-radius: var(--radius-control); cursor:pointer;\">送信</button></td>' +
        '</tr>';
    }).join('');

    unsubmittedBody.querySelectorAll('tr').forEach(function(tr) {
      tr.addEventListener('mouseenter', function() { tr.style.background = 'var(--bg-sidebar)'; });
      tr.addEventListener('mouseleave', function() { tr.style.background = 'transparent'; });
    });
    unsubmittedBody.querySelectorAll('.btn-remind').forEach(function(btn) {
      btn.addEventListener('click', function() {
        var uid = btn.getAttribute('data-user-id');
        var user = userById(uid);
        reminderTarget = { type: 'single', userId: uid };
        reminderMessage.textContent = (user ? user.氏名 : '対象者') + ' さんにリマインダーを送信しますか？';
        reminderOverlay.style.display = 'flex';
      });
    });
  }

  bulkReminderBtn.addEventListener('click', function() {
    var list = computeUnsubmitted();
    if (list.length === 0) {
      showStatus('未提出者はいません');
      return;
    }
    reminderTarget = { type: 'bulk' };
    reminderMessage.textContent = '未提出者全員（' + list.length + '件）にリマインダーを送信しますか？';
    reminderOverlay.style.display = 'flex';
  });

  confirmReminderBtn.addEventListener('click', function() {
    if (!reminderTarget) { closeModals(); return; }
    var now = new Date().toISOString();
    var targets = reminderTarget.type === 'single' ? [reminderTarget.userId] : computeUnsubmitted().map(function(i) { return i.userId; });
    var sentCount = 0;
    var chain = Promise.resolve();
    targets.forEach(function(uid) {
      chain = chain.then(function() {
        if (mailIndex === -1) return null;
        var user = userById(uid);
        return window.aivicApi.save(mailIndex, {
          ユーザーID: uid,
          メールタイプ: 'リマインダー',
          送信先メールアドレス: (user && user.メールアドレス) || 'unknown@example.com',
          件名: '【リマインダー】本日の日報提出をお願いします',
          本文: (user ? user.氏名 : '') + '様、本日の日報がまだ提出されていません。ご提出をお願いします。',
          送信日時: now,
          送信ステータス: '成功',
          再送信フラグ: false,
          作成日時: now
        }).then(function(ok) { if (ok) sentCount++; });
      });
    });
    chain.then(function() {
      closeModals();
      showStatus('リマインダーを ' + sentCount + ' 件送信しました');
    });
  });

  searchInput.addEventListener('input', function() {
    renderSubmitted(searchInput.value.trim());
  });

  settingsBtn.addEventListener('click', function() {
    if (window.showScreen) window.showScreen('scr-1789983420568');
  });

  backToInputBtn.addEventListener('click', function() {
    if (window.showScreen) window.showScreen('scr-1789983412165');
  });

  renderSubmitted('');
  renderUnsubmitted();
}
